pou.interface:
{implicit on}
FUNCTION __HelpConvertLDate : BOOL
VAR_INPUT
  in : ULINT;
  ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
  nSeconds: UDINT;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}

    nSeconds := ULINT_TO_UDINT(in / ULINT#1_000_000_000);
    __HelpConvertDate(nSeconds, ppstr);

		{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertLTime : BOOL
VAR_INPUT
  in : ULINT;
  ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
  nNanoseconds: UDINT;
  nSeconds: UDINT;
  nMilliseconds: UDINT;
  pstr: POINTER TO BYTE;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}

    nSeconds := ULINT_TO_UDINT(in / ULINT#1_000_000_000);
    nMilliseconds := nSeconds * UDINT#1_000;
    __HelpConvertTime(nMilliseconds, ppstr);

    nNanoseconds := ULINT_TO_UDINT(in MOD ULINT#1_000_000_000);
    IF (nNanoseconds <> 0) THEN	
	    pstr := ppstr^;
	    pstr[0] := 16#2E; (*'.'*)
	    pstr := pstr + 1;
	    __HelpConvert(nNanoseconds, ADR(pstr), 9);
    END_IF

    ppstr^ := pstr;

		{implicit off}

