pou.interface:
{implicit on}
FUNCTION __HelpConvertLTimeW : BOOL
VAR_INPUT
  in : ULINT;
  ppstr : POINTER TO POINTER TO WORD;
END_VAR
VAR
  nNanoseconds: UDINT;
  nSeconds: UDINT;
  nMilliseconds: UDINT;
  pstr: POINTER TO WORD;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}

    nSeconds := ULINT_TO_UDINT(in / ULINT#1_000_000_000);
    nMilliseconds := nSeconds * UDINT#1_000;
    __HelpConvertTimeW(nMilliseconds, ppstr);

    nNanoseconds := ULINT_TO_UDINT(in MOD ULINT#1_000_000_000);
    IF (nNanoseconds <> 0) THEN	
	    pstr := ppstr^;
	    pstr[0] := 16#002E; (*'.'*)
      pstr := pstr + SIZEOF(WORD);
	    __HelpConvertW(nNanoseconds, ADR(pstr), 9);
    END_IF

    ppstr^ := pstr;

		{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertFromLTime : ULINT
VAR_INPUT
  ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
  pstr : POINTER TO BYTE := ppstr^;
  pszNanoseconds: POINTER TO BYTE;
  pszTemp: POINTER TO BYTE;
  ulNanoseconds: ULINT;
  udiNanosecondsLength: DWORD;
  ulHelpLdt: ULINT;        
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}

			pszTemp := pstr;
      WHILE (pszTemp[0] <> 16#0) DO
        IF (pszTemp^ = 16#2E (*'.'*) AND pszNanoseconds = 16#0) THEN
          pszNanoseconds := pszTemp;
          pszNanoseconds^ := 16#0;
          pszNanoseconds := pszNanoseconds + 1;              
        END_IF

				pszTemp := pszTemp+1;
			END_WHILE

			__HelpConvertFromLTime := UDINT_TO_ULINT(__HelpConvertFromTime(ADR(pstr))) * ULINT#1_000_000;

      IF (pszNanoseconds <> 16#0) THEN
          udiNanosecondsLength := TO_UDINT(pszTemp - pszNanoseconds);
          ulNanoseconds := LREAL_TO_ULINT(ULINT_TO_LREAL(__HelpConvertString(pszNanoseconds,udiNanosecondsLength)) * EXPT(10,9 - udiNanosecondsLength));                    
          __HelpConvertFromLTime := __HelpConvertFromLTime + ulNanoseconds;
      END_IF       

		{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertFromLDate : ULINT
