{implicit on}
FUNCTION __HelpConvertFromLTimeW : ULINT
VAR_INPUT
  ppstr : POINTER TO POINTER TO WORD;
END_VAR
VAR
  pstr : POINTER TO WORD := ppstr^;
  pszNanoseconds: POINTER TO WORD;
  pszTemp: POINTER TO WORD;
  ulNanoseconds: ULINT;
  udiNanosecondsLength: DWORD;
  ulHelpLdt: ULINT;        
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}

			pszTemp := pstr;
      WHILE (pszTemp[0] <> 16#0) DO
        IF (pszTemp^ = 16#002E (*'.'*) AND pszNanoseconds = 16#0) THEN
          pszNanoseconds := pszTemp;
          pszNanoseconds^ := 16#0;
          pszNanoseconds := pszNanoseconds + SIZEOF(WORD);              
        END_IF

				pszTemp := pszTemp + SIZEOF(WORD);
			END_WHILE

			__HelpConvertFromLTimeW := UDINT_TO_ULINT(__HelpConvertFromTimeW(ADR(pstr))) * ULINT#1_000_000;

      IF (pszNanoseconds <> 16#0) THEN
          udiNanosecondsLength := TO_UDINT((pszTemp - pszNanoseconds) / 2);
          ulNanoseconds := LREAL_TO_ULINT(ULINT_TO_LREAL(__HelpConvertStringW(pszNanoseconds,udiNanosecondsLength)) * EXPT(10,9 - udiNanosecondsLength));                    
          __HelpConvertFromLTimeW := __HelpConvertFromLTimeW + ulNanoseconds;
      END_IF       

		{implicit off}

